    title: "صوت مكالمة FaceTime منخفض جداً على Mac؟ كيف تصلحه",
    description:
      "صوت FaceTime بالكاد مسموع على Mac حتى على أقصى صوت. إليك كل إصلاح — من إعدادات الصوت لتعزيز FaceTime فوق 100%.",
